"use client";

import type { HTMLMotionProps, Variants } from "motion/react";
import { motion, useAnimation, useReducedMotion } from "motion/react";
import { forwardRef, useEffect, useImperativeHandle, useRef } from "react";

const EASE_IN_OUT: [number, number, number, number] = [0.77, 0, 0.175, 1];
const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];

export interface RocketHandle {
	startAnimation: () => void;
	stopAnimation: () => void;
}

interface RocketProps extends HTMLMotionProps<"div"> {
	size?: number;
	duration?: number;
	isAnimated?: boolean;
	intervalDuration?: number;
}

const RocketIcon = forwardRef<RocketHandle, RocketProps>(
	(
		{
			className,
			size = 24,
			duration = 1,
			isAnimated = true,
			intervalDuration = 3000,
			...props
		},
		ref,
	) => {
		const controls = useAnimation();
		const reduced = useReducedMotion();
		const isControlled = useRef(false);

		useImperativeHandle(ref, () => {
			isControlled.current = true;
			return {
				startAnimation: () =>
					reduced ? controls.start("normal") : controls.start("animate"),
				stopAnimation: () => controls.start("normal"),
			};
		});

		useEffect(() => {
			if (!isAnimated || reduced) return;

			if (!isControlled.current) {
				controls.start("animate");
			}

			const intervalId = setInterval(() => {
				if (!isControlled.current) {
					controls.start("animate");
				}
			}, intervalDuration);

			return () => clearInterval(intervalId);
		}, [controls, isAnimated, reduced, intervalDuration]);

		const rocketVariants: Variants = {
			normal: { transform: "translate(0px, 0px)" },
			animate: {
				transform: [
					"translate(0px, 0px)",
					"translate(3px, -3px)",
					"translate(0px, 0px)",
				],
				transition: {
					duration: 0.7 * duration,
					ease: EASE_IN_OUT,
				},
			},
		};

		const thrustVariants: Variants = {
			normal: { opacity: 1, transform: "scale(1)" },
			animate: {
				opacity: [1, 0.3, 1],
				transform: ["scale(1)", "scale(1.4)", "scale(1)"],
				transition: {
					duration: 0.4 * duration,
					ease: EASE_IN_OUT,
				},
			},
		};

		return (
			<motion.div
				className={`inline-flex items-center justify-center ${className ?? ""}`}
				{...props}
			>
				<motion.svg
					xmlns="http://www.w3.org/2000/svg"
					width={size}
					height={size}
					viewBox="0 0 24 24"
					fill="none"
					stroke="currentColor"
					strokeWidth="2"
					strokeLinecap="round"
					strokeLinejoin="round"
					aria-hidden="true"
					focusable="false"
				>
					<motion.path
						d="m12 15-3-3a22 22 0 0 1 2-3.95A12.88 12.88 0 0 1 22 2c0 2.72-.78 7.5-6 11a22.35 22.35 0 0 1-4 2z"
						variants={rocketVariants}
						initial="normal"
						animate={controls}
						style={{
							transformBox: "fill-box",
							transformOrigin: "center",
						}}
					/>
					<motion.path
						d="M9 12H4s.55-3.03 2-4c1.62-1.08 5 0 5 0"
						variants={rocketVariants}
						initial="normal"
						animate={controls}
						style={{
							transformBox: "fill-box",
							transformOrigin: "center",
						}}
					/>
					<motion.path
						d="M12 15v5s3.03-.55 4-2c1.08-1.62 0-5 0-5"
						variants={rocketVariants}
						initial="normal"
						animate={controls}
						style={{
							transformBox: "fill-box",
							transformOrigin: "center",
						}}
					/>
					<motion.path
						d="M4.5 16.5c-1.5 1.26-2 5-2 5s3.74-.5 5-2c.71-.84.7-2.13-.09-2.91a2.18 2.18 0 0 0-2.91-.09z"
						variants={thrustVariants}
						initial="normal"
						animate={controls}
						style={{
							transformBox: "fill-box",
							transformOrigin: "center",
						}}
					/>
				</motion.svg>
			</motion.div>
		);
	},
);

