					"--gt-u": size === "sm" ? `calc(1px * ${SIZE_SCALE.sm})` : "1px",
					"--gt-sx": "0%",
					"--gt-sy": "0%",
					...initial.vars,
					width: u(TRACK_WIDTH),
					height: u(TRACK_HEIGHT),
					...style,
