"use client";

import { useTiks } from "@rexa-developer/tiks/react";
import {
	AnimatePresence,
	type AnimationPlaybackControls,
	animate,
	motion,
	useMotionValue,
	useReducedMotion,
} from "motion/react";
import {
	type KeyboardEvent,
	memo,
	type PointerEvent,
	useCallback,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
} from "react";
import { useWebHaptics } from "web-haptics/react";
import { cn } from "@/lib/utils";

const landingSpring = { type: "spring", stiffness: 420, damping: 38 } as const;
const digitTransition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] } as const;

/** Seconds of release velocity that a flick coasts before it snaps. */
const COAST_SECONDS = 0.25;
/** Fastest release, in px/s, so one jumpy pointer event can't fling the range. */
const MAX_VELOCITY = 4000;
/** Furthest the strip travels past a bound, in px. */
const MAX_OVERSHOOT = 40;
/** Minimum ms between step sounds and haptics. */
const TICK_THROTTLE_MS = 35;
/** Pointer travel, in px, below which a press counts as a tap. */
const TAP_SLOP = 5;
/** Ranges with more ticks than this render only the ticks near the needle. */
const WINDOW_THRESHOLD = 400;

const sizes = {
	sm: { spacing: 8, track: "h-14", readout: "text-3xl", unit: "text-sm" },
	md: { spacing: 10, track: "h-16", readout: "text-5xl", unit: "text-base" },
	lg: { spacing: 12, track: "h-20", readout: "text-6xl", unit: "text-lg" },
} as const;

type Orientation = "horizontal" | "vertical";
type RulerState = "idle" | "dragging" | "coasting";

export interface TickRulerProps {
	/** Controlled value. */
	value?: number;
	/** Initial value when uncontrolled; double-click resets to it. */
	defaultValue?: number;
	/** Called every time the needle crosses onto a new step. */
	onValueChange?: (value: number) => void;
	/** Called once the ruler settles after a drag, flick, key, wheel, or preset. */
	onValueCommit?: (value: number) => void;
	min?: number;
	max?: number;
	step?: number;
	/** Steps between medium ticks. */
	majorEvery?: number;
	/** Steps between labelled ticks. */
	labelEvery?: number;
	/** Pixels between ticks. Defaults by `size`. */
	spacing?: number;
	/** Unit shown after the readout, e.g. `min`. */
	unit?: string;
	/** Formats the readout and `aria-valuetext`. */
	format?: (value: number) => string;
	/** Values shown as chips that glide the ruler to them. */
	presets?: number[];
	/** Play a click per step and a pop at the bounds. */
	sound?: boolean;
	/** Trigger haptics on supported devices. */
	haptics?: boolean;
	disabled?: boolean;
	/** Accessible name for the slider. */
	label?: string;
	className?: string;
	size?: keyof typeof sizes;
	orientation?: Orientation;
	/** Show the large value readout above the ruler. */
	showValue?: boolean;
}

function decimalsOf(value: number) {
	const text = String(value);
	if (text.includes("e-")) return Number(text.split("e-")[1]);
	return text.split(".")[1]?.length ?? 0;
}

function clamp(value: number, min: number, max: number) {
	return Math.min(Math.max(value, min), max);
}

/** Pulls travel past a bound back so it never exceeds `MAX_OVERSHOOT`. */
function rubberBand(position: number, maxPosition: number) {
	if (position < 0) {
		const over = -position;
		return -(MAX_OVERSHOOT * over) / (over + MAX_OVERSHOOT);
	}
	if (position > maxPosition) {
		const over = position - maxPosition;
		return maxPosition + (MAX_OVERSHOOT * over) / (over + MAX_OVERSHOOT);
	}
	return position;
}

type DigitSlot = { char: string; id: number };

let nextDigitId = 0;

/** Aligns `text` to `previous` from the right, keeping ids of unchanged chars. */
function toSlots(text: string, previous: DigitSlot[]): DigitSlot[] {
	const chars = text.split("");
	return chars.map((char, index) => {
		const match = previous[previous.length - chars.length + index];
		if (match?.char === char) return match;
		nextDigitId += 1;
		return { char, id: nextDigitId };
	});
}

function RollingValue({
	text,
	direction,
	animated,
}: {
	text: string;
	direction: number;
	animated: boolean;
}) {
	// Each slot gets a fresh key whenever its character changes. Reusing a key
	// while its previous copy is still exiting can leave the digit hidden.
	const [slots, setSlots] = useState(() => toSlots(text, []));
	const [previousText, setPreviousText] = useState(text);
	if (text !== previousText) {
		setPreviousText(text);
		setSlots((previous) => toSlots(text, previous));
	}

	if (!animated) return <span>{text}</span>;

	return (
		<span className="inline-flex">
			{slots.map(({ char, id }, index) => (
				// Keyed from the right so units digits stay put as the width changes.
				<span key={slots.length - index} className="relative inline-block">
					<AnimatePresence mode="popLayout" initial={false} custom={direction}>
						<motion.span
							key={id}
							custom={direction}
							className="inline-block"
							variants={{
								enter: (d: number) => ({ y: d * 12, opacity: 0 }),
								center: { y: 0, opacity: 1 },
								exit: (d: number) => ({ y: d * -12, opacity: 0 }),
							}}
							initial="enter"
							animate="center"
							exit="exit"
							transition={digitTransition}
						>
							{char}
						</motion.span>
					</AnimatePresence>
				</span>
			))}
		</span>
	);
}

const TickStrip = memo(function TickStrip({
	start,
	end,
	spacing,
	sign,
	orientation,
	majorEvery,
	labelEvery,
	labelAt,
}: {
	start: number;
	end: number;
	spacing: number;
	sign: number;
	orientation: Orientation;
	majorEvery: number;
	labelEvery: number;
	labelAt: (index: number) => string;
}) {
	const horizontal = orientation === "horizontal";
	const ticks = [];
	for (let index = start; index <= end; index++) {
		const kind =
			index % labelEvery === 0
				? "label"
				: index % majorEvery === 0
					? "major"
					: "minor";
		const offset = sign * index * spacing;
		ticks.push(
			<span
				key={index}
				data-kind={kind}
				className={cn(
					"absolute flex items-center gap-1.5",
					horizontal
						? "top-0 -translate-x-1/2 flex-col"
						: "left-0 -translate-y-1/2 flex-row",
				)}
				style={horizontal ? { left: offset } : { top: offset }}
			>
				<span
					className={cn(
						"rounded-full",
						horizontal ? "w-px" : "h-px",
						kind === "minor" && "bg-muted-foreground/35",
						kind === "minor" && (horizontal ? "h-3" : "w-3"),
						kind === "major" && "bg-muted-foreground/60",
						kind === "major" && (horizontal ? "h-5" : "w-5"),
						kind === "label" && "bg-foreground/80",
						kind === "label" &&
							(horizontal ? "h-7 w-[1.5px]" : "h-[1.5px] w-7"),
					)}
				/>
				{kind === "label" ? (
					<span className="font-medium text-[11px] text-muted-foreground tabular-nums leading-none">
						{labelAt(index)}
					</span>
				) : null}
			</span>,
		);
	}
	return <>{ticks}</>;
});

export function TickRuler({
	value: valueProp,
	defaultValue,
	onValueChange,
	onValueCommit,
	min = 0,
	max = 100,
	step = 1,
	majorEvery = 5,
	labelEvery = 10,
	spacing: spacingProp,
	unit,
	format,
	presets,
	sound = true,
	haptics = true,
	disabled = false,
	label = "Value",
	className,
	size = "md",
	orientation = "horizontal",
	showValue = true,
}: TickRulerProps) {
	const sizeStyle = sizes[size];
	const spacing = spacingProp ?? sizeStyle.spacing;
	const horizontal = orientation === "horizontal";
	const decimals = Math.max(decimalsOf(step), decimalsOf(min));
	const maxIndex = Math.max(0, Math.round((max - min) / step));
	const maxPosition = maxIndex * spacing;

	const indexToValue = useCallback(
		(index: number) => Number((min + index * step).toFixed(decimals)),
		[min, step, decimals],
	);
	const valueToIndex = useCallback(
		(value: number) => clamp(Math.round((value - min) / step), 0, maxIndex),
		[min, step, maxIndex],
	);
	const formatValue = useCallback(
		(value: number) => (format ? format(value) : value.toFixed(decimals)),
		[format, decimals],
	);

	const initialIndex = valueToIndex(valueProp ?? defaultValue ?? min);
	const [currentIndex, setCurrentIndex] = useState(initialIndex);
	const [direction, setDirection] = useState(1);
	const [sign, setSign] = useState(horizontal ? 1 : -1);
	const [range, setRange] = useState(() =>
		maxIndex + 1 <= WINDOW_THRESHOLD
			? { start: 0, end: maxIndex }
			: {
					start: Math.max(0, initialIndex - 60),
					end: Math.min(maxIndex, initialIndex + 60),
				},
	);

	const shouldReduceMotion = useReducedMotion() ?? false;
	const { trigger: haptic } = useWebHaptics();
	const { click: playClick, pop: playPop } = useTiks({
		// Sound stays on under reduced motion; only movement is reduced.
		respectReducedMotion: false,
	});

	const rootRef = useRef<HTMLDivElement>(null);
	const trackRef = useRef<HTMLDivElement>(null);
	const position = useMotionValue(initialIndex * spacing);
	const stripOffset = useMotionValue(0);
	const centerRef = useRef(0);
	const indexRef = useRef(initialIndex);
	const animationRef = useRef<AnimationPlaybackControls | null>(null);
	const silentRef = useRef(false);
	const interactingRef = useRef(false);
	const lastTickAtRef = useRef(Number.NEGATIVE_INFINITY);
	const chunkRef = useRef(-1);
	const wheelRef = useRef({ accumulated: 0, target: initialIndex });
	const dragRef = useRef<{
		pointerId: number;
		start: number;
		startPosition: number;
		moved: boolean;
		scale: number;
	} | null>(null);

	// Latest values for the imperative listeners below, so they never re-bind.
	const latest = useRef({
		sound,
		haptics,
		onValueChange,
		onValueCommit,
		indexToValue,
		maxIndex,
		maxPosition,
		spacing,
		sign,
		labelEvery,
	});
	useLayoutEffect(() => {
		latest.current = {
			sound,
			haptics,
			onValueChange,
			onValueCommit,
			indexToValue,
			maxIndex,
			maxPosition,
			spacing,
			sign,
			labelEvery,
		};
	});

	const setRulerState = useCallback((state: RulerState) => {
		if (rootRef.current) rootRef.current.dataset.state = state;
	}, []);

	const updateRange = useCallback((pos: number) => {
		const { maxIndex, spacing } = latest.current;
		if (maxIndex + 1 <= WINDOW_THRESHOLD) {
			if (chunkRef.current !== 0) {
				chunkRef.current = 0;
				setRange({ start: 0, end: maxIndex });
			}
			return;
		}
		const visible = Math.ceil((centerRef.current * 2) / spacing) || 60;
		const chunkSize = Math.max(40, visible);
		const chunk = Math.floor(pos / spacing / chunkSize);
		if (chunk === chunkRef.current) return;
		chunkRef.current = chunk;
		setRange({
			start: Math.max(0, (chunk - 1) * chunkSize),
			end: Math.min(maxIndex, (chunk + 2) * chunkSize),
		});
	}, []);

	// The one place that reacts to movement: transforms, ticks, and feedback.
	useEffect(() => {
		const sync = (pos: number) => {
			const {
				sign,
				spacing,
				maxIndex,
				indexToValue,
				labelEvery,
				sound,
				haptics,
				onValueChange,
			} = latest.current;
			stripOffset.set(centerRef.current - sign * pos);
			updateRange(pos);

			const index = clamp(Math.round(pos / spacing), 0, maxIndex);
			const previous = indexRef.current;
			if (index === previous) return;
			indexRef.current = index;
			setCurrentIndex(index);
			setDirection(index > previous ? 1 : -1);
			if (silentRef.current) return;

			onValueChange?.(indexToValue(index));
			const now = performance.now();
			const atBound = index === 0 || index === maxIndex;
			// Bounds always sound so a fast flick still ends on the pop.
			if (!atBound && now - lastTickAtRef.current < TICK_THROTTLE_MS) return;
			lastTickAtRef.current = now;
			if (atBound) {
				if (sound) playPop();
				if (haptics) void haptic("rigid");
			} else {
				if (sound) playClick();
				if (haptics)
					void haptic(index % labelEvery === 0 ? "light" : "selection");
			}
		};
		sync(position.get());
		return position.on("change", sync);
	}, [haptic, playClick, playPop, position, stripOffset, updateRange]);

	// Track size and direction.
	useLayoutEffect(() => {
		const track = trackRef.current;
		if (!track) return;
		const measure = () => {
			const rtl = getComputedStyle(track).direction === "rtl";
			const nextSign = horizontal ? (rtl ? -1 : 1) : -1;
			latest.current.sign = nextSign;
			setSign(nextSign);
			centerRef.current =
				(horizontal ? track.offsetWidth : track.offsetHeight) / 2;
			chunkRef.current = -1;
			stripOffset.set(centerRef.current - nextSign * position.get());
			updateRange(position.get());
		};
		measure();
		const observer = new ResizeObserver(measure);
		observer.observe(track);
		return () => observer.disconnect();
	}, [horizontal, position, stripOffset, updateRange]);

	// Spacing or range changes keep the current step under the needle.
	// biome-ignore lint/correctness/useExhaustiveDependencies: re-run when the range changes too
	useEffect(() => {
		chunkRef.current = -1;
		position.jump(indexRef.current * spacing);
	}, [position, spacing, maxIndex]);

	const stop = useCallback(() => {
		animationRef.current?.stop();
		animationRef.current = null;
	}, []);

	const settle = useCallback(
		(
			targetIndex: number,
			{
				velocity = 0,
				silent = false,
				onLand,
			}: { velocity?: number; silent?: boolean; onLand?: () => void } = {},
		) => {
			stop();
			const target = clamp(targetIndex, 0, latest.current.maxIndex);
			const targetPosition = target * latest.current.spacing;
			silentRef.current = silent;
			const finish = () => {
				animationRef.current = null;
				silentRef.current = false;
				setRulerState("idle");
				if (!silent) {
					latest.current.onValueCommit?.(latest.current.indexToValue(target));
					onLand?.();
				}
			};
			if (shouldReduceMotion || position.get() === targetPosition) {
				position.jump(targetPosition);
				finish();
				return;
			}
			setRulerState("coasting");
			animationRef.current = animate(position, targetPosition, {
				...landingSpring,
				velocity,
				restDelta: 0.01,
				onComplete: finish,
			});
		},
		[position, setRulerState, shouldReduceMotion, stop],
	);

	// Controlled value: glide there silently unless the user is interacting.
	useEffect(() => {
		if (valueProp === undefined || interactingRef.current) return;
		const target = valueToIndex(valueProp);
		if (target === indexRef.current && !animationRef.current) return;
		if (animationRef.current && !silentRef.current) return;
		settle(target, { silent: true });
	}, [valueProp, valueToIndex, settle]);

	useEffect(() => stop, [stop]);

	const pointerAxis = (event: PointerEvent) =>
		horizontal ? event.clientX : event.clientY;

	const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
		if (disabled || event.button !== 0) return;
		const track = event.currentTarget;
		track.setPointerCapture(event.pointerId);
		track.focus({ preventScroll: true });
		stop();
		silentRef.current = false;
		interactingRef.current = true;
		const rect = track.getBoundingClientRect();
		// CSS zoom and transforms scale client coordinates; work in local px.
		const scale = horizontal
			? rect.width / (track.offsetWidth || 1)
			: rect.height / (track.offsetHeight || 1);
		dragRef.current = {
			pointerId: event.pointerId,
			start: pointerAxis(event),
			startPosition: position.get(),
			moved: false,
			scale: scale || 1,
		};
	};

	const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		const delta = (pointerAxis(event) - drag.start) / drag.scale;
		if (!drag.moved) {
			if (Math.abs(delta) < TAP_SLOP) return;
			drag.moved = true;
			setRulerState("dragging");
		}
		const raw = drag.startPosition - sign * delta;
		position.set(rubberBand(raw, maxPosition));
	};

	const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
		const drag = dragRef.current;
		if (!drag || drag.pointerId !== event.pointerId) return;
		dragRef.current = null;
		interactingRef.current = false;
		const track = event.currentTarget;
		if (track.hasPointerCapture(event.pointerId)) {
			track.releasePointerCapture(event.pointerId);
		}

		if (!drag.moved) {
			// Tap: glide to the tick under the pointer.
			const rect = track.getBoundingClientRect();
			const local =
				(pointerAxis(event) - (horizontal ? rect.left : rect.top)) / drag.scale;
			const offset = sign * (local - centerRef.current);
			settle(Math.round((position.get() + offset) / spacing));
			return;
		}

		const velocity = clamp(position.getVelocity(), -MAX_VELOCITY, MAX_VELOCITY);
		const current = position.get();
		const coast = shouldReduceMotion ? 0 : velocity * COAST_SECONDS;
		const target = clamp(current + coast, 0, maxPosition);
		settle(Math.round(target / spacing), { velocity });
	};

	const handlePointerCancel = (event: PointerEvent<HTMLDivElement>) => {
		if (dragRef.current?.pointerId !== event.pointerId) return;
		dragRef.current = null;
		interactingRef.current = false;
		settle(Math.round(clamp(position.get(), 0, maxPosition) / spacing));
	};

	const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
		if (disabled) return;
		const stepBy = event.shiftKey ? 10 : 1;
		const flip = horizontal && sign < 0 ? -1 : 1;
		// Repeated keys build on the pending target, not the moving needle.
		const from = animationRef.current
			? wheelRef.current.target
			: indexRef.current;
		let target: number | null = null;
		switch (event.key) {
			case "ArrowRight":
				target = from + stepBy * flip;
				break;
			case "ArrowLeft":
				target = from - stepBy * flip;
				break;
			case "ArrowUp":
				target = from + stepBy;
				break;
			case "ArrowDown":
				target = from - stepBy;
				break;
			case "PageUp":
				target = from + 10;
				break;
			case "PageDown":
				target = from - 10;
				break;
			case "Home":
				target = 0;
				break;
			case "End":
				target = maxIndex;
				break;
			default:
				return;
		}
		event.preventDefault();
		target = clamp(target, 0, maxIndex);
		wheelRef.current.target = target;
		settle(target);
	};

	// Wheel needs a non-passive listener to keep the page from scrolling.
	useEffect(() => {
		const track = trackRef.current;
		if (!track || disabled) return;
		const onWheel = (event: WheelEvent) => {
			const { sign, maxIndex, spacing } = latest.current;
			const along = horizontal ? event.deltaX : event.deltaY;
			const across = horizontal ? event.deltaY : event.deltaX;
			let delta = 0;
			if (Math.abs(along) >= Math.abs(across)) {
				delta = sign * along;
			} else if (horizontal && document.activeElement === track) {
				// A plain mouse wheel only drives a focused horizontal ruler.
				delta = -across;
			} else {
				return;
			}
			event.preventDefault();
			const wheel = wheelRef.current;
			if (!animationRef.current) wheel.target = indexRef.current;
			let steps = 0;
			if (event.deltaMode !== 0 || Math.abs(delta) >= 50) {
				// One notch, one step.
				steps = Math.sign(delta);
				wheel.accumulated = 0;
			} else {
				wheel.accumulated += delta;
				steps = Math.trunc(wheel.accumulated / spacing);
				wheel.accumulated -= steps * spacing;
			}
			if (steps === 0) return;
			const target = clamp(wheel.target + steps, 0, maxIndex);
			if (target === wheel.target) return;
			wheel.target = target;
			settle(target);
		};
		track.addEventListener("wheel", onWheel, { passive: false });
		return () => track.removeEventListener("wheel", onWheel);
	}, [disabled, horizontal, settle]);

	// iOS can still scroll the page under a captured pointer; block it mid-drag.
	useEffect(() => {
		const track = trackRef.current;
		if (!track) return;
		const onTouchMove = (event: TouchEvent) => {
			if (dragRef.current?.moved) event.preventDefault();
		};
		track.addEventListener("touchmove", onTouchMove, { passive: false });
		return () => track.removeEventListener("touchmove", onTouchMove);
	}, []);

	const currentValue = indexToValue(currentIndex);
	const valueText = format
		? format(currentValue)
		: `${formatValue(currentValue)}${unit ? ` ${unit}` : ""}`;
	const labelAt = useCallback(
		(index: number) => indexToValue(index).toFixed(decimals),
		[indexToValue, decimals],
	);
	const defaultIndex = valueToIndex(defaultValue ?? min);

	return (
		<div
			ref={rootRef}
			data-slot="tick-ruler"
			data-state="idle"
			data-orientation={orientation}
			data-disabled={disabled || undefined}
			data-bound={
				currentIndex === 0
					? "min"
					: currentIndex === maxIndex
						? "max"
						: undefined
			}
			className={cn(
				"group/ruler flex select-none gap-4 [--tick-ruler-accent:var(--color-orange-500)] data-disabled:opacity-50",
				horizontal ? "w-full flex-col items-center" : "flex-row items-center",
				className,
			)}
		>
			{showValue ? (
				<div
					aria-hidden
					data-slot="tick-ruler-value"
					className={cn(
						"flex items-baseline gap-1.5 font-semibold text-foreground tabular-nums tracking-tight",
						sizeStyle.readout,
					)}
				>
					<RollingValue
						text={formatValue(currentValue)}
						direction={direction}
						animated={!shouldReduceMotion}
					/>
					{unit && !format ? (
						<span
							className={cn(
								"font-medium text-muted-foreground tracking-normal",
								sizeStyle.unit,
							)}
						>
							{unit}
						</span>
					) : null}
				</div>
			) : null}

			<div
				ref={trackRef}
				role="slider"
				tabIndex={disabled ? -1 : 0}
				aria-label={label}
				aria-orientation={orientation}
				aria-valuemin={min}
				aria-valuemax={max}
				aria-valuenow={currentValue}
				aria-valuetext={valueText}
				aria-disabled={disabled || undefined}
				data-slot="tick-ruler-track"
				onPointerDown={handlePointerDown}
				onPointerMove={handlePointerMove}
				onPointerUp={handlePointerUp}
				onPointerCancel={handlePointerCancel}
				onKeyDown={handleKeyDown}
				onDoubleClick={() => {
					if (!disabled) settle(defaultIndex);
				}}
				className={cn(
					"relative cursor-grab overflow-hidden rounded-lg outline-none focus-visible:ring-3 focus-visible:ring-ring/50 group-data-disabled/ruler:pointer-events-none group-data-[state=dragging]/ruler:cursor-grabbing",
					horizontal
						? cn(
								"w-full touch-pan-y [mask-image:linear-gradient(to_right,transparent,black_18%,black_82%,transparent)]",
								sizeStyle.track,
							)
						: "h-64 w-20 touch-none [mask-image:linear-gradient(to_bottom,transparent,black_18%,black_82%,transparent)]",
				)}
			>
				<motion.div
					aria-hidden
					className={cn(
						"absolute will-change-transform",
						horizontal ? "top-2 left-0" : "top-0 left-3",
					)}
					style={horizontal ? { x: stripOffset } : { y: stripOffset }}
				>
					<TickStrip
						start={range.start}
						end={range.end}
						spacing={spacing}
						sign={sign}
						orientation={orientation}
						majorEvery={majorEvery}
						labelEvery={labelEvery}
						labelAt={labelAt}
					/>
				</motion.div>

				<span
					aria-hidden
					data-slot="tick-ruler-needle"
					className={cn(
						"pointer-events-none absolute rounded-full bg-[var(--tick-ruler-accent)] transition-[transform,box-shadow] duration-200 ease-out group-hover/ruler:scale-110 group-data-[state=dragging]/ruler:scale-115 group-data-[state=dragging]/ruler:shadow-[0_0_12px_2px_var(--tick-ruler-accent)]",
						horizontal
							? "top-1 left-1/2 h-9 w-[3px] origin-top -translate-x-1/2"
							: "top-1/2 left-1 h-[3px] w-11 origin-left -translate-y-1/2",
					)}
				/>
			</div>

			{presets?.length ? (
				<div
					data-slot="tick-ruler-presets"
					className={cn(
						"flex flex-wrap gap-2",
						horizontal ? "justify-center" : "flex-col",
					)}
				>
					{presets.map((preset) => {
						const active = valueToIndex(preset) === currentIndex;
						return (
							<button
								key={preset}
								type="button"
								disabled={disabled}
								data-active={active || undefined}
								onClick={() =>
									settle(valueToIndex(preset), {
										onLand: () => {
											if (haptics) void haptic("nudge");
										},
									})
								}
								className="h-8 cursor-pointer rounded-full border border-border bg-background px-3.5 font-medium text-muted-foreground text-sm tabular-nums shadow-xs outline-none transition-[color,background-color,border-color] hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none data-active:border-transparent data-active:bg-foreground data-active:text-background dark:border-input dark:bg-input/30 dark:data-active:bg-foreground"
							>
								{format ? format(preset) : formatValue(preset)}
								{unit && !format ? ` ${unit}` : null}
							</button>
						);
					})}
				</div>
			) : null}
		</div>
	);
}

"use client";

import { Trash2Icon } from "lucide-react";
import {
	AnimatePresence,
	type HTMLMotionProps,
	motion,
	useReducedMotion,
	useTransform,
} from "motion/react";
import { type ReactNode, useId } from "react";
import {
	type UseHoldToConfirmOptions,
	useHoldToConfirm,
} from "@/hooks/use-hold-to-confirm";
import { cn } from "@/lib/utils";

const labelTransition = {
	type: "spring",
	duration: 0.3,
	bounce: 0,
} as const;

function HoldToConfirmCheck() {
	return (
		<svg
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			strokeWidth={2.5}
			strokeLinecap="round"
			strokeLinejoin="round"
			aria-hidden
			data-slot="confirmed-icon"
		>
			<motion.path
				d="M5 12.5l4.5 4.5L19 7.5"
				initial={{ pathLength: 0 }}
				animate={{ pathLength: 1 }}
				transition={{ duration: 0.35, delay: 0.08, ease: [0.23, 1, 0.32, 1] }}
			/>
		</svg>
	);
}

type HeldHandler =
	| "onPointerDown"
	| "onPointerUp"
	| "onPointerCancel"
	| "onLostPointerCapture"
	| "onKeyDown"
	| "onKeyUp"
	| "onBlur"
	| "onContextMenu";

export type HoldToConfirmProps = Omit<
	HTMLMotionProps<"button">,
	"children" | HeldHandler
> &
	UseHoldToConfirmOptions & {
		/** Label shown while idle and under the fill. */
		children?: ReactNode;
		/** Icon shown before the label. */
		icon?: ReactNode;
		/** Label shown after the hold completes. */
		confirmedLabel?: ReactNode;
		/** Icon shown after the hold completes. Defaults to an animated checkmark. */
		confirmedIcon?: ReactNode;
		/** Description announced to assistive technology. */
		instructions?: string;
		/** Class name for the fill layer, e.g. to change its color. */
		fillClassName?: string;
	};

export function HoldToConfirm({
	className,
	children = "Hold to delete",
	icon = <Trash2Icon data-slot="idle-icon" />,
	confirmedLabel = "Deleted",
	confirmedIcon,
	instructions = "Press and hold to confirm",
	fillClassName,
	holdDuration,
	resetDelay,
	onConfirm,
	onCancel,
	sound,
	haptics,
	disabled,
	...props
}: HoldToConfirmProps) {
	const { state, progress, fillOpacity, handlers } = useHoldToConfirm({
		holdDuration,
		resetDelay,
		onConfirm,
		onCancel,
		sound,
		haptics,
		disabled,
	});
	const shouldReduceMotion = useReducedMotion();
	const descriptionId = useId();
	const clipPath = useTransform(progress, (value) => {
		const clamped = Math.min(Math.max(value, 0), 1);
		return `inset(0 ${(1 - clamped) * 100}% 0 0)`;
	});
	const isHolding = state === "holding";
	const isConfirmed = state === "confirmed";

	return (
		<>
			<motion.button
				type="button"
				data-slot="hold-to-confirm"
				data-state={state}
				disabled={disabled}
				aria-describedby={descriptionId}
				aria-disabled={isConfirmed || undefined}
				animate={{ scale: isHolding && !shouldReduceMotion ? 0.97 : 1 }}
				transition={{
					type: "spring",
					visualDuration: isHolding ? 0.2 : 0.4,
					bounce: isHolding ? 0 : 0.45,
				}}
				className={cn(
					"relative inline-flex h-10 shrink-0 cursor-pointer touch-manipulation select-none items-center justify-center whitespace-nowrap rounded-full border border-border bg-background px-5 font-medium text-foreground text-sm shadow-xs outline-none transition-[background-color,box-shadow] [-webkit-touch-callout:none] hover:bg-muted focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 dark:border-input dark:bg-input/30 dark:hover:bg-input/50 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
					className,
				)}
				{...handlers}
				{...props}
			>
				<span className="inline-flex items-center gap-2">
					{icon}
					{children}
				</span>

				<motion.span
					aria-hidden
					data-slot="hold-to-confirm-fill"
					style={{ clipPath, opacity: fillOpacity }}
					className={cn(
						"pointer-events-none absolute -inset-px flex items-center justify-center rounded-[inherit] border border-transparent bg-destructive px-5 text-white dark:bg-red-600",
						fillClassName,
					)}
				>
					<AnimatePresence mode="popLayout" initial={false}>
						<motion.span
							key={isConfirmed ? "confirmed" : "idle"}
							initial={{ opacity: 0, scale: 0.9, filter: "blur(4px)" }}
							animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
							exit={{ opacity: 0, scale: 0.9, filter: "blur(4px)" }}
							transition={labelTransition}
							className="inline-flex items-center gap-2"
						>
							{isConfirmed ? (confirmedIcon ?? <HoldToConfirmCheck />) : icon}
							{isConfirmed ? confirmedLabel : children}
						</motion.span>
					</AnimatePresence>
				</motion.span>
			</motion.button>

			<span id={descriptionId} className="sr-only">
				{instructions}
			</span>
			<span aria-live="polite" className="sr-only">
				{isConfirmed ? confirmedLabel : null}
			</span>
		</>
	);
}

"use client";

import {
	type AnimationPlaybackControls,
	animate,
	useMotionValue,
	useMotionValueEvent,
	useReducedMotion,
} from "motion/react";
import type { KeyboardEvent, PointerEvent } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { useWebHaptics } from "web-haptics/react";

export type HoldState = "idle" | "holding" | "confirmed";

export type UseHoldToConfirmOptions = {
	/** How long the button must be held before confirming, in milliseconds. */
	holdDuration?: number;
	/** Delay before returning to idle after confirming. Pass `false` to stay confirmed. */
	resetDelay?: number | false;
	/** Called once the hold completes. */
	onConfirm?: () => void;
	/** Called with the reached progress (0-1) when the hold is released early. */
	onCancel?: (progress: number) => void;
	/** Play a rising tone while holding and a chime on confirm. */
	sound?: boolean;
	/** Tick haptics while holding and a success pattern on confirm. */
	haptics?: boolean;
	/** Ignore all hold input. */
	disabled?: boolean;
};

const TICK_COUNT = 10;
// The riser climbs two octaves from G3 to G5, then resolves up to a C6 chime.
const MIN_FREQUENCY = 196;
const MAX_FREQUENCY = 784;
const CHIME_FREQUENCIES = [1046.5, 1568];

let audioContext: AudioContext | null = null;

function getAudioContext() {
	if (typeof window === "undefined" || !("AudioContext" in window)) {
		return null;
	}

	audioContext ??= new AudioContext();
	if (audioContext.state === "suspended") void audioContext.resume();
	return audioContext;
}

function frequencyAt(progress: number) {
	return MIN_FREQUENCY * (MAX_FREQUENCY / MIN_FREQUENCY) ** progress;
}

function holdParam(param: AudioParam, time: number) {
	if (typeof param.cancelAndHoldAtTime === "function") {
		param.cancelAndHoldAtTime(time);
		return;
	}

	const value = param.value;
	param.cancelScheduledValues(time);
	param.setValueAtTime(value, time);
}

type Riser = {
	release: () => void;
	finish: () => void;
};

function startRiser(progress: number, remaining: number): Riser | null {
	const ctx = getAudioContext();
	if (!ctx) return null;

	const now = ctx.currentTime;
	const oscillator = ctx.createOscillator();
	const filter = ctx.createBiquadFilter();
	const gain = ctx.createGain();

	oscillator.type = "triangle";
	oscillator.frequency.setValueAtTime(frequencyAt(progress), now);
	oscillator.frequency.exponentialRampToValueAtTime(
		MAX_FREQUENCY,
		now + Math.max(remaining, 0.01),
	);

	filter.type = "lowpass";
	filter.frequency.value = 2400;

	gain.gain.setValueAtTime(0, now);
	gain.gain.linearRampToValueAtTime(0.05, now + 0.05);

	oscillator.connect(filter).connect(gain).connect(ctx.destination);
	oscillator.start(now);

	let stopped = false;
	const stop = (fade: number, drop: boolean) => {
		if (stopped) return;
		stopped = true;

		const time = ctx.currentTime;
		holdParam(oscillator.frequency, time);
		holdParam(gain.gain, time);
		if (drop) {
			oscillator.frequency.exponentialRampToValueAtTime(
				MIN_FREQUENCY,
				time + fade,
			);
		}
		gain.gain.linearRampToValueAtTime(0, time + fade);
		oscillator.stop(time + fade + 0.02);
	};

	return {
		release: () => stop(0.18, true),
		finish: () => stop(0.04, false),
	};
}

function playChime() {
	const ctx = getAudioContext();
	if (!ctx) return;

	const now = ctx.currentTime;
	CHIME_FREQUENCIES.forEach((frequency, index) => {
		const start = now + index * 0.08;
		const oscillator = ctx.createOscillator();
		const gain = ctx.createGain();

		oscillator.type = "sine";
		oscillator.frequency.value = frequency;
		gain.gain.setValueAtTime(0, start);
		gain.gain.linearRampToValueAtTime(0.08, start + 0.005);
		gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.6);

		oscillator.connect(gain).connect(ctx.destination);
		oscillator.start(start);
		oscillator.stop(start + 0.65);
	});
}

function isHoldKey(key: string) {
	return key === " " || key === "Enter";
}

export function useHoldToConfirm({
	holdDuration = 1500,
	resetDelay = 2000,
	onConfirm,
	onCancel,
	sound = true,
	haptics = true,
	disabled = false,
}: UseHoldToConfirmOptions = {}) {
	const [state, setState] = useState<HoldState>("idle");
	const stateRef = useRef<HoldState>("idle");
	const progress = useMotionValue(0);
	const fillOpacity = useMotionValue(1);
	const animationRef = useRef<AnimationPlaybackControls | null>(null);
	const riserRef = useRef<Riser | null>(null);
	const resetTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
	const lastTickRef = useRef(0);
	const callbacksRef = useRef({ onConfirm, onCancel });
	const { trigger: haptic } = useWebHaptics();

	// Sound follows the same reduced-motion opt-out as the other TentUI sounds.
	const shouldReduceMotion = useReducedMotion();
	const soundEnabled = sound && !shouldReduceMotion;

	useEffect(() => {
		callbacksRef.current = { onConfirm, onCancel };
	}, [onConfirm, onCancel]);

	const updateState = useCallback((next: HoldState) => {
		stateRef.current = next;
		setState(next);
	}, []);

	const clearResetTimeout = useCallback(() => {
		if (resetTimeoutRef.current) {
			clearTimeout(resetTimeoutRef.current);
			resetTimeoutRef.current = null;
		}
	}, []);

	const reset = useCallback(() => {
		clearResetTimeout();
		animationRef.current?.stop();

		if (stateRef.current !== "confirmed") {
			progress.set(0);
			updateState("idle");
			return;
		}

		animationRef.current = animate(fillOpacity, 0, {
			duration: 0.2,
			ease: [0.23, 1, 0.32, 1],
			onComplete: () => {
				progress.set(0);
				fillOpacity.set(1);
				updateState("idle");
			},
		});
	}, [clearResetTimeout, fillOpacity, progress, updateState]);

	const confirm = useCallback(() => {
		updateState("confirmed");
		progress.set(1);

		riserRef.current?.finish();
		riserRef.current = null;
		if (soundEnabled) playChime();
		if (haptics) void haptic("success");

		callbacksRef.current.onConfirm?.();

		if (resetDelay !== false) {
			resetTimeoutRef.current = setTimeout(reset, resetDelay);
		}
	}, [haptic, haptics, progress, reset, resetDelay, soundEnabled, updateState]);

	const start = useCallback(() => {
		if (disabled || stateRef.current !== "idle") return;

		updateState("holding");
		const from = Math.min(Math.max(progress.get(), 0), 1);
		const remaining = (holdDuration / 1000) * (1 - from);
		lastTickRef.current = Math.floor(from * TICK_COUNT);

		animationRef.current?.stop();
		animationRef.current = animate(progress, 1, {
			duration: remaining,
			ease: "linear",
			onComplete: confirm,
		});

		if (soundEnabled) riserRef.current = startRiser(from, remaining);
		if (haptics) void haptic([{ duration: 10, intensity: 0.4 }]);
	}, [
		confirm,
		disabled,
		haptic,
		haptics,
		holdDuration,
		progress,
		soundEnabled,
		updateState,
	]);

	const cancel = useCallback(() => {
		if (stateRef.current !== "holding") return;

		updateState("idle");
		const reached = progress.get();

		animationRef.current?.stop();
		animationRef.current = animate(
			progress,
			0,
			shouldReduceMotion
				? { duration: 0.2, ease: [0.23, 1, 0.32, 1] }
				: { type: "spring", visualDuration: 0.35, bounce: 0.2 },
		);

		riserRef.current?.release();
		riserRef.current = null;

		callbacksRef.current.onCancel?.(reached);
	}, [progress, shouldReduceMotion, updateState]);

	// Tick a little harder at each step so the phone feels the hold building.
	useMotionValueEvent(progress, "change", (value) => {
		if (!haptics || stateRef.current !== "holding") return;

		const tick = Math.floor(value * TICK_COUNT);
		if (tick > lastTickRef.current && tick < TICK_COUNT) {
			lastTickRef.current = tick;
			void haptic([{ duration: 8, intensity: 0.3 + 0.6 * value }]);
		}
	});

	useEffect(() => {
		if (disabled) cancel();
	}, [disabled, cancel]);

	useEffect(() => {
		return () => {
			clearResetTimeout();
			animationRef.current?.stop();
			riserRef.current?.finish();
		};
	}, [clearResetTimeout]);

	const handlers = {
		onPointerDown: (event: PointerEvent<HTMLElement>) => {
			if (event.button !== 0) return;
			event.currentTarget.setPointerCapture(event.pointerId);
			start();
		},
		onPointerUp: cancel,
		onPointerCancel: cancel,
		onLostPointerCapture: cancel,
		onKeyDown: (event: KeyboardEvent<HTMLElement>) => {
			if (!isHoldKey(event.key)) return;
			event.preventDefault();
			if (!event.repeat) start();
		},
		onKeyUp: (event: KeyboardEvent<HTMLElement>) => {
			if (isHoldKey(event.key)) cancel();
		},
		onBlur: cancel,
		onContextMenu: (event: { preventDefault: () => void }) => {
			event.preventDefault();
		},
	};

	return { state, progress, fillOpacity, handlers, reset } as const;
}

"use client";

import type { CSSProperties } from "react";
import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

type SpriteFrame = {
	column: number;
	row: number;
};

type Direction =
	| "center"
	| "east"
	| "north"
	| "north-east"
	| "north-west"
	| "south"
	| "south-east"
	| "south-west"
	| "west";

export type DirectionFrameMap = Record<Direction, SpriteFrame>;

export type InteractiveSpriteProps = {
	/** Accessible description for the character. Use an empty string when decorative. */
	alt: string;
	/** Number of equally sized columns in the sprite sheet. */
	columns?: number;
	/** Distance from the character's center that keeps the resting frame active. */
	deadZone?: number;
	/** Maps pointer directions to cells in the sprite sheet. */
	frames?: DirectionFrameMap;
	/** Time without pointer movement before returning to the center frame. */
	idleDelay?: number;
	/** Number of equally sized rows in the sprite sheet. */
	rows?: number;
	/** Public URL for the sprite sheet. */
	src: string;
	className?: string;
	style?: CSSProperties;
};

const DEFAULT_FRAMES: DirectionFrameMap = {
	"north-west": { column: 0, row: 0 },
	north: { column: 1, row: 0 },
	"north-east": { column: 2, row: 0 },
	west: { column: 0, row: 1 },
	center: { column: 1, row: 1 },
	east: { column: 2, row: 1 },
	"south-west": { column: 0, row: 2 },
	south: { column: 1, row: 2 },
	"south-east": { column: 2, row: 2 },
};

const OCTANTS: Direction[] = [
	"east",
	"south-east",
	"south",
	"south-west",
	"west",
	"north-west",
	"north",
	"north-east",
];

function getDirection(deltaX: number, deltaY: number, deadZone: number) {
	if (Math.hypot(deltaX, deltaY) <= deadZone) return "center";

	const octant =
		(Math.round(Math.atan2(deltaY, deltaX) / (Math.PI / 4)) + 8) % 8;

	return OCTANTS[octant];
}

function getBackgroundPosition(
	frame: SpriteFrame,
	columns: number,
	rows: number,
) {
	const x = columns === 1 ? 0 : (frame.column / (columns - 1)) * 100;
	const y = rows === 1 ? 0 : (frame.row / (rows - 1)) * 100;

	return `${x}% ${y}%`;
}

export function InteractiveSprite({
	alt,
	className,
	columns = 3,
	deadZone = 24,
	frames = DEFAULT_FRAMES,
	idleDelay = 300,
	rows = 3,
	src,
	style,
}: InteractiveSpriteProps) {
	const rootRef = useRef<HTMLSpanElement>(null);
	const activeDirectionRef = useRef<Direction>("center");
	const [activeDirection, setActiveDirection] = useState<Direction>("center");

	useEffect(() => {
		const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
		let animationFrame: number | null = null;
		let idleTimeout: number | undefined;

		const resetDirection = () => {
			if (activeDirectionRef.current === "center") return;

			activeDirectionRef.current = "center";
			setActiveDirection("center");
		};

		const handlePointerMove = (event: PointerEvent) => {
			if (event.pointerType === "touch" || reducedMotion.matches) return;

			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);

			animationFrame = requestAnimationFrame(() => {
				animationFrame = null;
				const root = rootRef.current;
				if (!root || reducedMotion.matches) return;

				const bounds = root.getBoundingClientRect();
				const direction = getDirection(
					event.clientX - (bounds.left + bounds.width / 2),
					event.clientY - (bounds.top + bounds.height / 2),
					deadZone,
				);

				if (direction !== activeDirectionRef.current) {
					activeDirectionRef.current = direction;
					setActiveDirection(direction);
				}

				idleTimeout = window.setTimeout(resetDirection, idleDelay);
			});
		};

		const handleMotionPreferenceChange = () => {
			if (reducedMotion.matches) resetDirection();
		};

		window.addEventListener("pointermove", handlePointerMove, {
			passive: true,
		});
		reducedMotion.addEventListener("change", handleMotionPreferenceChange);

		return () => {
			window.removeEventListener("pointermove", handlePointerMove);
			reducedMotion.removeEventListener("change", handleMotionPreferenceChange);
			window.clearTimeout(idleTimeout);
			if (animationFrame !== null) cancelAnimationFrame(animationFrame);
		};
	}, [deadZone, idleDelay]);

	const frame = frames[activeDirection];
	const spriteStyle: CSSProperties = {
		backgroundImage: `url("${src}")`,
		backgroundPosition: getBackgroundPosition(frame, columns, rows),
		backgroundRepeat: "no-repeat",
		backgroundSize: `${columns * 100}% ${rows * 100}%`,
	};
	const accessibilityProps = alt
		? { "aria-label": alt, role: "img" }
		: { "aria-hidden": true as const };

	return (
		<span
			ref={rootRef}
			className={cn("block overflow-hidden", className)}
			data-direction={activeDirection}
			data-slot="interactive-sprite"
			style={style}
			{...accessibilityProps}
		>
			<span
				aria-hidden="true"
				className="block size-full"
				style={spriteStyle}
			/>
		</span>
	);
}

"use client";

import type { ComponentProps } from "react";
import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

const TAU = Math.PI * 2;
const MAX_SIZE = 0.9;
const SPEED = 0.02;
const ALPHA_STEPS = 6;

const clamp = (value: number, min: number, max: number) =>
	Math.min(max, Math.max(min, value));

function smoothstep(value: number, edge0: number, edge1: number) {
	const t = clamp((value - edge0) / (edge1 - edge0), 0, 1);
	return t * t * (3 - 2 * t);
}

function hash(x: number, y: number) {
	const value = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
	return value - Math.floor(value);
}

class TileFieldEngine {
	private canvas: HTMLCanvasElement;
	private ctx: CanvasRenderingContext2D;
	private host: HTMLElement;
	private color: string;
	private reducedMotion: boolean;
	private restColor = "gray";
	private word: string;

	private dpr = Math.min(2, window.devicePixelRatio || 1);
	private viewW = 0;
	private viewH = 0;
	private cell = 10;
	private time = 0;

	private n = 0;
	private px = new Float32Array(0);
	private py = new Float32Array(0);
	private drawX = new Float32Array(0);
	private drawY = new Float32Array(0);
	private spark = new Uint8Array(0);
	private lit = new Float32Array(0);
	private seed = new Float32Array(0);

	private hasPointer = false;
	private rawX = 0;
	private rawY = 0;
	private lightX = 0;
	private lightY = 0;
	private lightSpeed = 0;
	private raf = 0;

	constructor(host: HTMLElement, word: string, color: string) {
		this.host = host;
		this.word = word;
		this.color = color;
		this.canvas = document.createElement("canvas");
		this.canvas.className =
			"pointer-events-none absolute inset-0 block size-full";
		this.canvas.setAttribute("aria-hidden", "true");
		this.ctx = this.canvas.getContext("2d")!;
		this.host.appendChild(this.canvas);
		this.reducedMotion = window.matchMedia(
			"(prefers-reduced-motion: reduce)",
		).matches;

		this.resize();
		this.host.addEventListener("pointermove", this.onMove, { passive: true });
		this.host.addEventListener("pointerleave", this.onLeave);
	}

	resize() {
		const rect = this.host.getBoundingClientRect();
		this.viewW = rect.width;
		this.viewH = rect.height;
		this.dpr = Math.min(2, window.devicePixelRatio || 1);
		this.cell = Math.max(2, Math.round(this.viewW / 460));

		this.canvas.style.width = `${Math.round(this.viewW)}px`;
		this.canvas.style.height = `${Math.round(this.viewH)}px`;
		this.canvas.width = Math.ceil(this.viewW * this.dpr);
		this.canvas.height = Math.ceil(this.viewH * this.dpr);
		this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
		this.ctx.imageSmoothingEnabled = false;
		this.updateTheme();

		const source = document.createElement("canvas");
		source.width = Math.max(1, Math.floor(this.viewW));
		source.height = Math.max(1, Math.floor(this.viewH));
		const sourceCtx = source.getContext("2d")!;
		const spacedCtx = sourceCtx as CanvasRenderingContext2D & {
			letterSpacing?: string;
		};
		sourceCtx.fillStyle = "#000";
		sourceCtx.textAlign = "center";
		sourceCtx.textBaseline = "middle";

		let fontSize = this.viewH * 0.9;
		spacedCtx.letterSpacing = `${-0.02 * fontSize}px`;
		sourceCtx.font = `600 ${fontSize}px ui-sans-serif, system-ui, Arial, sans-serif`;
		const measuredWidth = sourceCtx.measureText(this.word).width || 1;
		fontSize *= (this.viewW * 0.92) / measuredWidth;
		spacedCtx.letterSpacing = `${-0.02 * fontSize}px`;
		sourceCtx.font = `600 ${fontSize}px ui-sans-serif, system-ui, Arial, sans-serif`;
		sourceCtx.fillText(this.word, this.viewW / 2, this.viewH / 2);

		const data = sourceCtx.getImageData(0, 0, source.width, source.height).data;
		const xs: number[] = [];
		const ys: number[] = [];
		const sparks: number[] = [];
		const seeds: number[] = [];
		const columns = Math.ceil(this.viewW / this.cell);
		const rows = Math.ceil(this.viewH / this.cell);

		for (let row = 0; row < rows; row++) {
			for (let column = 0; column < columns; column++) {
				const x = Math.floor(column * this.cell + this.cell / 2);
				const y = Math.floor(row * this.cell + this.cell / 2);
				if (x >= source.width || y >= source.height) continue;

				const alpha = (data[(y * source.width + x) * 4 + 3] ?? 0) / 255;
				if (alpha <= 0.5) continue;

				xs.push(x);
				ys.push(y);
				sparks.push(hash(x + 7, y - 3) > 0.82 ? 1 : 0);
				seeds.push(hash(x * 1.3, y * 0.7));
			}
		}

		this.n = xs.length;
		this.px = new Float32Array(xs);
		this.py = new Float32Array(ys);
		this.drawX = new Float32Array(xs);
		this.drawY = new Float32Array(ys);
		this.spark = new Uint8Array(sparks);
		this.seed = new Float32Array(seeds);
		this.lit = new Float32Array(this.n);

		if (this.reducedMotion) this.renderStatic();
	}

	private distSegSq(
		qx: number,
		qy: number,
		ax: number,
		ay: number,
		bx: number,
		by: number,
	) {
		const dx = bx - ax;
		const dy = by - ay;
		if (dx === 0 && dy === 0) {
			const ex = qx - ax;
			const ey = qy - ay;
			return ex * ex + ey * ey;
		}

		const t = clamp(
			((qx - ax) * dx + (qy - ay) * dy) / (dx * dx + dy * dy),
			0,
			1,
		);
		const ex = qx - (ax + dx * t);
		const ey = qy - (ay + dy * t);
		return ex * ex + ey * ey;
	}

	private frame = (timestamp: number) => {
		const { viewW, viewH, cell, n, px, py } = this;
		const drawX = this.drawX;
		const drawY = this.drawY;
		const spark = this.spark;
		const lit = this.lit;
		const seed = this.seed;
		this.ctx.clearRect(0, 0, viewW, viewH);
		this.time += SPEED;
		const time = this.time;

		const previousX = this.lightX;
		const previousY = this.lightY;
		if (this.hasPointer) {
			this.lightX += (this.rawX - this.lightX) * 0.5;
			this.lightY += (this.rawY - this.lightY) * 0.5;
		}

		const lightX = this.lightX;
		const lightY = this.lightY;
		const stepDistance = Math.hypot(lightX - previousX, lightY - previousY);
		this.lightSpeed = 0.9 * this.lightSpeed + 0.1 * stepDistance;

		const reach = clamp(
			viewH * 0.22 + this.lightSpeed * 0.9,
			viewH * 0.18,
			viewH * 0.42,
		);
		const influence = 1.5 * reach;
		const influenceSq = influence * influence;
		const minX = Math.min(previousX, lightX) - influence;
		const maxX = Math.max(previousX, lightX) + influence;
		const minY = Math.min(previousY, lightY) - influence;
		const maxY = Math.max(previousY, lightY) + influence;

		const grayPath = new Path2D();
		const litList: number[] = [];
		const buckets = Array.from({ length: ALPHA_STEPS }, () => new Path2D());

		for (let index = 0; index < n; index++) {
			const x = px[index];
			const y = py[index];
			let target = 0;

			if (this.hasPointer && x >= minX && x <= maxX && y >= minY && y <= maxY) {
				const distanceSq = this.distSegSq(
					x,
					y,
					previousX,
					previousY,
					lightX,
					lightY,
				);
				if (distanceSq <= influenceSq) {
					const angle = Math.atan2(y - lightY, x - lightX);
					const wobble =
						1 +
						0.3 * Math.sin(3 * angle + time * 1.6) +
						0.16 * Math.sin(5 * angle - time * 1.1 + 1.3);
					const amount = clamp(
						1 - Math.sqrt(distanceSq) / (reach * wobble),
						0,
						1,
					);
					target = amount * amount * (3 - 2 * amount);
				}
			}

			const rate = target > lit[index] ? 0.24 : 0.02;
			lit[index] += (target - lit[index]) * rate;

			const pointerX = x - lightX;
			const pointerY = y - lightY;
			const pointerDistance = Math.max(1, Math.hypot(pointerX, pointerY));
			const motion =
				lit[index] *
				cell *
				(0.65 + 0.2 * Math.sin(seed[index] * TAU + time * 2));
			const drift = lit[index] * cell * 0.18;
			const tileX =
				x +
				(pointerX / pointerDistance) * motion +
				Math.sin(seed[index] * TAU + time * 2.4) * drift;
			const tileY =
				y +
				(pointerY / pointerDistance) * motion +
				Math.cos(seed[index] * TAU - time * 2) * drift;
			drawX[index] = tileX;
			drawY[index] = tileY;

			const u = x / Math.max(viewW, 1);
			const v = y / Math.max(viewH, 1);
			const flow =
				Math.sin((u * 1.6 + 0.4 * Math.sin(time * 0.3)) * TAU + time * 0.8) +
				0.7 * Math.sin((v * 2.1 - u * 0.9) * TAU - time * 0.6 + 1.7) +
				0.5 * Math.sin((u * 3.3 + v * 2.7) * TAU + time * 0.4 + 4.2) +
				0.4 *
					Math.cos((v * 1.3 - 1.1 * Math.sin(time * 0.2)) * TAU - time * 0.5);
			let colorAmount = smoothstep(flow, 0.1, 1.6);
			colorAmount = Math.max(colorAmount, lit[index]);

			const breathe = 0.5 + 0.5 * Math.sin(seed[index] * TAU + time * 1.3);
			const base = 0.42 + 0.08 * breathe;
			const size = cell * (base + (MAX_SIZE - base) * colorAmount);
			const half = size / 2;
			grayPath.rect(tileX - half, tileY - half, size, size);

			if (colorAmount > 0.04) {
				const alphaStep = Math.min(
					ALPHA_STEPS - 1,
					Math.floor(colorAmount * ALPHA_STEPS),
				);
				buckets[alphaStep].rect(tileX - half, tileY - half, size, size);
			}

			if (lit[index] > 0.02) litList.push(index);
		}

		this.ctx.fillStyle = this.restColor;
		this.ctx.fill(grayPath);

		this.ctx.fillStyle = this.color;
		for (let alphaStep = 0; alphaStep < ALPHA_STEPS; alphaStep++) {
			this.ctx.globalAlpha = (alphaStep + 1) / ALPHA_STEPS;
			this.ctx.fill(buckets[alphaStep]);
		}
		this.ctx.globalAlpha = 1;

		for (const index of litList) {
			const light = lit[index];
			const x = drawX[index];
			const y = drawY[index];
			const glowSize = cell * (0.7 + (MAX_SIZE - 0.7) * light);
			const glowHalf = glowSize / 2;

			if (spark[index]) {
				const phase = seed[index];
				const sparkTime = 0.00025 * timestamp;
				const amplitude = (0.45 + phase) * cell * 0.28;
				const jitterX =
					x + Math.sin(0.05 * x + 1.3 * sparkTime + phase * TAU) * amplitude;
				const jitterY =
					y + Math.cos(0.04 * y - 0.9 * sparkTime + phase * TAU) * amplitude;
				this.ctx.globalAlpha = 0.1 * light;
				this.ctx.fillStyle = this.color;
				this.ctx.fillRect(
					jitterX - glowHalf * 1.5,
					jitterY - glowHalf * 1.5,
					glowSize * 1.5,
					glowSize * 1.5,
				);
				this.ctx.globalAlpha = 0.55 * light;
				this.ctx.fillRect(
					jitterX - glowHalf,
					jitterY - glowHalf,
					glowSize,
					glowSize,
				);
			} else {
				this.ctx.globalAlpha = 0.85 * light;
				this.ctx.fillStyle = this.color;
				this.ctx.fillRect(x - glowHalf, y - glowHalf, glowSize, glowSize);
			}
		}
		this.ctx.globalAlpha = 1;

		this.raf = requestAnimationFrame(this.frame);
	};

	renderStatic() {
		this.ctx.clearRect(0, 0, this.viewW, this.viewH);
		const path = new Path2D();
		for (let index = 0; index < this.n; index++) {
			const size = this.cell * 0.5;
			const half = size / 2;
			path.rect(this.px[index] - half, this.py[index] - half, size, size);
		}
		this.ctx.fillStyle = this.restColor;
		this.ctx.fill(path);
	}

	updateTheme() {
		this.restColor = getComputedStyle(this.host).color;
		if (this.reducedMotion) this.renderStatic();
	}

	setColor(color: string) {
		this.color = color;
	}

	setReducedMotion(reducedMotion: boolean) {
		this.reducedMotion = reducedMotion;
		if (reducedMotion) this.renderStatic();
	}

	private onMove = (event: PointerEvent) => {
		if (event.pointerType === "touch") return;

		const rect = this.host.getBoundingClientRect();
		const x = event.clientX - rect.left;
		const y = event.clientY - rect.top;
		if (!this.hasPointer) {
			this.hasPointer = true;
			this.lightX = x;
			this.lightY = y;
			this.lightSpeed = 0;
		}
		this.rawX = x;
		this.rawY = y;
	};

	private onLeave = () => {
		this.hasPointer = false;
	};

	start() {
		if (this.reducedMotion || this.raf) return;
		this.raf = requestAnimationFrame(this.frame);
	}

	stop() {
		if (this.raf) cancelAnimationFrame(this.raf);
		this.raf = 0;
	}

	destroy() {
		this.stop();
		this.host.removeEventListener("pointermove", this.onMove);
		this.host.removeEventListener("pointerleave", this.onLeave);
		this.canvas.remove();
	}
}

export interface TileFieldProps
	extends Omit<ComponentProps<"div">, "children" | "ref"> {
	/** Color used by the wave, pointer glow, and sparks. */
	color?: string;
	/** Text rendered into the tile grid. */
	word?: string;
}

export function TileField({
	"aria-label": ariaLabel,
	className,
	color = "#6366f1",
	word = "Localhost",
	...props
}: TileFieldProps) {
	const hostRef = useRef<HTMLDivElement>(null);
	const engineRef = useRef<TileFieldEngine>(null);
	const colorRef = useRef(color);
	colorRef.current = color;

	useEffect(() => {
		const host = hostRef.current;
		if (!host) return;

		const engine = new TileFieldEngine(host, word, colorRef.current);
		engineRef.current = engine;
		const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
		let isInView = true;

		const syncAnimation = () => {
			engine.setReducedMotion(motionQuery.matches);
			if (isInView && !document.hidden && !motionQuery.matches) {
				engine.start();
			} else {
				engine.stop();
			}
		};
		const resizeObserver = new ResizeObserver(() => engine.resize());
		const themeObserver = new MutationObserver(() => engine.updateTheme());
		const intersectionObserver = new IntersectionObserver(([entry]) => {
			isInView = entry?.isIntersecting ?? true;
			syncAnimation();
		});

		resizeObserver.observe(host);
		themeObserver.observe(document.documentElement, {
			attributeFilter: ["class", "style"],
			attributes: true,
		});
		intersectionObserver.observe(host);
		document.addEventListener("visibilitychange", syncAnimation);
		motionQuery.addEventListener("change", syncAnimation);
		syncAnimation();

		return () => {
			resizeObserver.disconnect();
			themeObserver.disconnect();
			intersectionObserver.disconnect();
			document.removeEventListener("visibilitychange", syncAnimation);
			motionQuery.removeEventListener("change", syncAnimation);
			engine.destroy();
			engineRef.current = null;
		};
	}, [word]);

	useEffect(() => engineRef.current?.setColor(color), [color]);

	return (
		<div
			aria-label={ariaLabel ?? word}
			className={cn(
				"relative isolate min-h-48 w-full overflow-hidden text-muted-foreground",
				className,
			)}
			data-slot="tile-field"
			ref={hostRef}
			role="img"
			{...props}
		/>
	);
}

"use client";

import { CopyIcon, CornerDownLeftIcon, SearchIcon } from "lucide-react";
import * as React from "react";
import { useHotkeys } from "react-hotkeys-hook";

import { Button } from "@/components/ui/button";
import {
	CommandDialog,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
	CommandShortcut,
} from "@/components/ui/command";
import { Kbd, KbdGroup } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";

export type SearchCommandItem = {
	/** Stable identity when items may be reordered. */
	id?: string;
	/** Primary searchable label. */
	title: string;
	/** Optional text included in search without being displayed. */
	description?: string;
	/** Overrides the value used by the command menu's filter. */
	value?: string;
	/** Additional terms that should match this item. */
	keywords?: readonly string[];
	icon?: React.ReactNode;
	/** Supporting metadata displayed at the end of the row. */
	meta?: React.ReactNode;
	/** Compact keyboard sequence displayed at the end of the row. */
	shortcut?: string;
	/** Overrides the footer action while this item is highlighted. */
	actionLabel?: string;
	disabled?: boolean;
	/** Runs immediately before the menu closes. */
	onBeforeSelect?: () => void;
	onSelect?: () => void;
};

export type SearchCommandGroup = {
	heading: string;
	items: readonly SearchCommandItem[];
	/** Footer action used by items in this group. */
	actionLabel?: string;
};

export type SearchCommandProps = {
	groups: readonly SearchCommandGroup[];
	/** Controlled dialog state. */
	open?: boolean;
	/** Initial dialog state when uncontrolled. */
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	onItemSelect?: (item: SearchCommandItem) => void;
	/** Enables the configured modifier shortcut and slash. */
	enabledHotkeys?: boolean;
	/** Character used with Command or Control to open the menu. */
	shortcutKey?: string;
	/** Overrides the modifier displayed in the trigger. */
	shortcutModifier?: "auto" | "command" | "control";
	triggerLabel?: string;
	triggerSlot?: string;
	placeholder?: string;
	emptyMessage?: React.ReactNode;
	title?: string;
	description?: string;
	footerIcon?: React.ReactNode;
	defaultActionLabel?: string;
	triggerClassName?: string;
	dialogClassName?: string;
	listClassName?: string;
};

export function SearchCommand({
	defaultActionLabel = "Open",
	defaultOpen = false,
	description = "Search for a command to run...",
	dialogClassName,
	emptyMessage = "No results found.",
	enabledHotkeys = false,
	footerIcon,
	groups,
	listClassName,
	onItemSelect,
	onOpenChange,
	open,
	placeholder = "Type a command or search…",
	shortcutKey = "k",
	shortcutModifier = "auto",
	title = "Command Palette",
	triggerClassName,
	triggerLabel = "Search…",
	triggerSlot = "command-menu-trigger",
}: SearchCommandProps) {
	const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
	const [selectedActionLabel, setSelectedActionLabel] =
		React.useState(defaultActionLabel);
	const isOpen = open ?? internalOpen;
	const normalizedShortcutKey = shortcutKey.trim().toLowerCase();
	const displayedShortcutKey = normalizedShortcutKey.toUpperCase();
	const ariaKeyShortcuts =
		shortcutModifier === "command"
			? `Meta+${displayedShortcutKey} /`
			: shortcutModifier === "control"
				? `Control+${displayedShortcutKey} /`
				: `Meta+${displayedShortcutKey} Control+${displayedShortcutKey} /`;

	const setOpen = React.useCallback(
		(nextOpen: boolean) => {
			if (open === undefined) setInternalOpen(nextOpen);
			onOpenChange?.(nextOpen);
		},
		[onOpenChange, open],
	);

	useHotkeys(
		`mod+${normalizedShortcutKey}, slash`,
		(event) => {
			event.preventDefault();
			setOpen(!isOpen);
		},
		{ enabled: enabledHotkeys },
	);

	function handleItemSelect(item: SearchCommandItem) {
		item.onBeforeSelect?.();
		setOpen(false);
		item.onSelect?.();
		onItemSelect?.(item);
	}

	return (
		<>
			<Button
				aria-expanded={isOpen}
				aria-haspopup="dialog"
				aria-keyshortcuts={ariaKeyShortcuts}
				aria-label={triggerLabel}
				className={cn(
					"select-none gap-1.5 border-none px-1.5 text-muted-foreground will-change-[scale]",
					triggerClassName,
				)}
				data-slot={triggerSlot}
				onClick={() => setOpen(true)}
				size="sm"
				variant="ghost"
			>
				<SearchIcon />
				<span className="font-medium font-sans text-sm/4 sm:hidden">
					{triggerLabel}
				</span>
				{shortcutModifier !== "control" ? (
					<KbdGroup
						className={cn(
							"hidden gap-0.75",
							shortcutModifier === "command"
								? "sm:flex"
								: "sm:in-[.os-macos_&]:flex",
						)}
					>
						<Kbd className="w-5 min-w-auto">⌘</Kbd>
						<Kbd className="w-5 min-w-auto">{displayedShortcutKey}</Kbd>
					</KbdGroup>
				) : null}
				{shortcutModifier !== "command" ? (
					<KbdGroup
						className={cn(
							"hidden gap-0.75",
							shortcutModifier === "control"
								? "sm:flex"
								: "sm:not-[.os-macos_&]:flex",
						)}
					>
						<Kbd>Ctrl</Kbd>
						<Kbd className="w-5 min-w-auto">{displayedShortcutKey}</Kbd>
					</KbdGroup>
				) : null}
			</Button>

			<CommandDialog
				className={dialogClassName}
				description={description}
				onOpenChange={setOpen}
				open={isOpen}
				title={title}
			>
				<SearchCommandInput placeholder={placeholder} />

				<div className="rounded-xl bg-background ring-1 ring-border">
					<CommandList className={cn("scroll-fade min-h-80", listClassName)}>
						<CommandEmpty>{emptyMessage}</CommandEmpty>
						{groups.map((group) => (
							<CommandGroup heading={group.heading} key={group.heading}>
								{group.items.map((item, index) => {
									const actionLabel =
										item.actionLabel ?? group.actionLabel ?? defaultActionLabel;
									const keywords = [
										...(item.keywords ?? []),
										...(item.description ? [item.description] : []),
									];
									return (
										<SearchCommandMenuItem
											disabled={item.disabled}
											key={item.id ?? `${item.value ?? item.title}-${index}`}
											keywords={keywords.length > 0 ? keywords : undefined}
											onHighlight={() => setSelectedActionLabel(actionLabel)}
											onSelect={() => handleItemSelect(item)}
											value={item.value}
										>
											{item.icon ?? <CopyIcon />}
											<p className="line-clamp-1">{item.title}</p>
											{item.meta ? (
												<span className="ml-auto font-mono font-normal text-muted-foreground text-xs tabular-nums max-sm:hidden">
													{item.meta}
												</span>
											) : null}
											{item.shortcut ? (
												<CommandShortcut className="font-mono tracking-[0.2em] max-sm:hidden">
													{item.shortcut}
												</CommandShortcut>
											) : null}
										</SearchCommandMenuItem>
									);
								})}
							</CommandGroup>
						))}
					</CommandList>
				</div>

				<div className="flex h-10" />
				<div className="absolute inset-x-0 bottom-0 flex h-10 items-center justify-between gap-2 rounded-b-2xl px-4 font-medium text-xs">
					<span className="size-4 shrink-0">
						{footerIcon ?? <SearchIcon className="size-full" />}
					</span>
					<div className="flex items-center gap-2 max-sm:hidden">
						<span>{selectedActionLabel}</span>
						<Kbd>
							<CornerDownLeftIcon />
						</Kbd>
					</div>
				</div>
			</CommandDialog>
		</>
	);
}

function SearchCommandInput({ placeholder }: { placeholder: string }) {
	const [searchValue, setSearchValue] = React.useState("");

	return (
		<CommandInput
			placeholder={placeholder}
			value={searchValue}
			onValueChange={setSearchValue}
		/>
	);
}

function SearchCommandMenuItem({
	children,
	onHighlight,
	...props
}: React.ComponentProps<typeof CommandItem> & {
	onHighlight?: () => void;
}) {
	const ref = React.useRef<HTMLDivElement>(null);

	React.useEffect(() => {
		const commandItem = ref.current;
		if (!commandItem) return;

		const observer = new MutationObserver(() => {
			if (commandItem.dataset.selected === "true") onHighlight?.();
		});
		observer.observe(commandItem, {
			attributes: true,
			attributeFilter: ["data-selected"],
		});

		return () => observer.disconnect();
	}, [onHighlight]);

	return (
		<CommandItem ref={ref} {...props}>
			{children}
		</CommandItem>
	);
}

